def ext(label):
 d={k:float(v) for k,v in (x.split('=') for x in (P/(label+'.PROCESS_WALL.txt')).read_text().split())};d['peak_bytes']=int(d['peak_KiB']*1024);d['CPU_seconds']=d['user_seconds']+d['system_seconds'];return d
bridge=json.loads((P/'bridge/results.json').read_text());assert bridge['complete'];rows=[]
for label in ORDER:
 j=json.loads((P/label/'results.json').read_text());assert j['complete'] and j['production_unchanged'] and j['E_unchanged'];assert j['operator_identity']==bridge['operator_identity'];assert j['source_hashes']==bridge['source_hashes'];assert j['probe_sha256']==bridge['probe_sha256']
 if j['method']!='angular':assert j['basis_identity']==bridge['basis_identity']
 apps=j['applications'];assert len(apps)==6 and all(a['passed'] and a['status']['success'] and a['status']['corrections']==1 for a in apps)
 c=j['cost'];setup=c['physical_and_basis_setup_total_wall_seconds']+c['factor_wall_seconds'];setcpu=c['physical_and_basis_setup_total_CPU_seconds']+c['factor_CPU_seconds'];application=sum(a['checked_inverse_wall_seconds'] for a in apps);checks=sum(a['independent_check_seconds'] for a in apps);raw=sum(a['raw_apply_wall_seconds']+a['diagnostic_check_seconds'] for a in j['raw_diagnostics']);io=c['reference_read_seconds'];validation=c['identity_validation_seconds'];accounted=setup+application+checks+raw+io+validation
 row=dict(label=label,method=j['method'],pid=j['pid'],results_sha256=sha(label+'/results.json'),factor_bytes=j['factor_bytes'],setup_wall_seconds=setup,setup_CPU_seconds=setcpu,physical_and_basis_setup_wall_seconds=c['physical_and_basis_setup_total_wall_seconds'],factor_wall_seconds=c['factor_wall_seconds'],factor_CPU_seconds=c['factor_CPU_seconds'],rotation_wall_seconds=sum(r.get('rotation_seconds',0.) for r in j.get('factor_records',[])),application_wall_seconds=application,independent_QA_seconds=checks,raw_diagnostics_and_checks_seconds=raw,reference_read_seconds=io,identity_validation_seconds=validation,profiled_workload_seconds=setup+application,profiled_workload_including_independent_QA_seconds=setup+application+checks,internal_process_wall_seconds=j['process_wall_seconds'],internal_process_CPU_seconds=j['process_CPU_seconds'],internal_unpartitioned_seconds=j['process_wall_seconds']-accounted,external=ext(label),max_original_residual=max(max(a['original_relative']) for a in apps),max_reference_difference=max(max(a['reference_difference']) for a in apps),applications=apps,raw_diagnostics=j['raw_diagnostics'],memory={k:j[k] for k in ['RSS_before_factor','RSS_after_factor','factor_phase_peak_RSS_bytes','application_phase_peak_RSS_bytes','peak_process_RSS_bytes','RSS_end']},resource_at_start=j['resource_at_start'],resource_at_end=j['resource_at_end'])
 for kind in ['single','mixed']:
  a=[x for x in apps if x['input']==kind];row[kind]=dict(setup_plus_first_seconds=setup+a[0]['checked_inverse_wall_seconds'],setup_plus_three_seconds=setup+sum(x['checked_inverse_wall_seconds'] for x in a),wall_seconds=[x['checked_inverse_wall_seconds'] for x in a],CPU_seconds=[x['checked_inverse_CPU_seconds'] for x in a],mean_wall_seconds=st.mean(x['checked_inverse_wall_seconds'] for x in a),first_wall_seconds=a[0]['checked_inverse_wall_seconds'],later_mean_wall_seconds=st.mean(x['checked_inverse_wall_seconds'] for x in a[1:]))
 rows.append(row)
