 for kind in ['single','mixed']:summary[method][kind]={k:st.mean(r[kind][k] for r in rs) for k in ['mean_wall_seconds','first_wall_seconds','later_mean_wall_seconds','setup_plus_first_seconds','setup_plus_three_seconds']}
 summary[method]['external_peak_bytes_range']=[min(r['external']['peak_bytes'] for r in rs),max(r['external']['peak_bytes'] for r in rs)];summary[method]['factor_bytes']=rs[0]['factor_bytes']
